import{_ as e,o as i,c as l,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Whats (in) a Build System? - Zack Cerza & John Mulligan, IBM","description":"","frontmatter":{"title":"Whats (in) a Build System? - Zack Cerza & John Mulligan, IBM","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","Build System","Containerization","Jenkins Pipeline","DevOps"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/What_s_in_a_Build_System_-_Zack_Cerza_John_Mulligan_IBM.md","filePath":"posts/2025/What_s_in_a_Build_System_-_Zack_Cerza_John_Mulligan_IBM.md","lastUpdated":1780459816000}'),a={name:"posts/2025/What_s_in_a_Build_System_-_Zack_Cerza_John_Mulligan_IBM.md"};function _(s,t,o,r,p,u){return i(),l("div",null,[...t[0]||(t[0]=[n("<p>本次会议主要讨论了Ceph构建系统的改进与容器化。以下是会议的主要内容：</p><p><strong>一、会议背景与现有问题</strong></p><ul><li>历史痛点：Ceph构建系统复杂且不可靠，开发者依赖人工调试，Legacy Build Jobs存在代码混乱、调试困难、效率低下等问题。</li><li>用户反馈：开发者对构建系统的使用感到困惑，包括如何在非Ubuntu/CentOS系统上构建，以及如何解决<code>make check</code>失败等问题。</li></ul><p><strong>二、解决方案：容器化构建与工具</strong></p><ul><li><strong>Build with Container (BWC)</strong>：通过OCI容器实现隔离与可移植性，封装依赖项和构建脚本，支持多平台，提供交互式Shell和自定义命令。</li><li><strong>新构建流水线（Jenkins Pipeline）</strong>：使用Groovy脚本，日志分阶段展示，支持指定提交和平台组合，效率提升。</li></ul><p><strong>三、性能优化与未来计划</strong></p><ul><li><strong>性能数据</strong>：构建时间从1小时降至20分钟，缓存命中显著提高。</li><li><strong>未来方向</strong>：分布式编译，构建取消优化，开发者工具扩展。</li></ul><p><strong>四、Q&amp;A 关键讨论</strong></p><ul><li>开发者体验反馈：增强BWC的灵活性，提供持久化容器模式。</li><li>安全与测试：默认支持Rootless容器，使用Ceph DevStack快速部署微集群。</li><li>日志与 CI 集成：通过插件分阶段查看日志，讨论将构建逻辑迁移至Ceph主仓库的可能性。</li></ul><p><strong>五、行动计划</strong></p><ul><li>开发者参与试用BWC并反馈问题，学习Git Trailer控制构建参数。</li><li>长期协作：每周三Ceph Build SIG会议讨论构建优化，探索与CBS Spir工具的代码复用。</li></ul><p>本次会议强调了容器化和Jenkins Pipeline在Ceph构建系统优化中的作用，并对未来的发展方向进行了探讨。通过改进构建系统，可以提高开发效率和用户体验，推动Ceph项目的进一步发展。</p>",12)])])}const c=e(a,[["render",_]]);export{g as __pageData,c as default};
